from pathlib import Path
import numpy as np
from PIL import Image,ImageDraw
from scipy.ndimage import label
R=Path(__file__).resolve().parents[3];B=R/'level-editor/work/active/croisement03';W=B/'restart2'
def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);out=p.parse_args().output;assert not(out/'receipt.json').exists();out.mkdir(exist_ok=True);pins={}
 def pin(path):pins[str(path)]=hashlib.sha256(path.read_bytes()).hexdigest();return path
 src=Image.open(pin(B/'baseline/covered.png')).convert('RGBA');source=np.array(src);inventory=json.loads(pin(B/'source-inventory.json').read_text());roles=json.loads(pin(W/'tree18-role-reconciliation-v1/receipt.json').read_text());pin(W/'tree18-full-source-context-v1/receipt.json');native=np.zeros(source.shape[:2],bool);phases=[]
 for i,row in enumerate(next(a for a in inventory['animations']if a['index']==4)['frames']):
  raw=np.array(Image.open(pin(Path(row['source']))).convert('RGBA'));assert pins[row['source']]==row['sha256'];raw[np.all(raw[:,:,:3]==[0,251,0],axis=2)]=0;rgba=np.array(Image.open(pin(Path(row['image']))).convert('RGBA'));assert np.array_equal(raw,rgba);x,y,w,h=row['bbox'];assert (w,h)==(rgba.shape[1],rgba.shape[0]);a=np.zeros(native.shape,bool);a[y:y+h,x:x+w]=rgba[:,:,3]>0;native|=a;phases.append(a)
 assert int(native.sum())==roles['counts']['native_union']==22406
 def polygon(points):
  mask=Image.new('L',src.size);ImageDraw.Draw(mask).polygon([tuple(p)for p in points],fill=255);return np.array(mask)>0
 rows=[{'id':'main-trunk-illuminated-bark','class':'illuminated_bark_proposal','context_box':[428,414,463,502],'visible_neighborhood':[[436,417],[448,419],[451,434],[454,450],[453,465],[453,477],[447,489],[438,490],[434,477],[435,462],[433,446],[434,431]],'interior_polygons':[[[440,420],[446,420],[447,429],[446,438],[449,449],[450,457],[448,466],[449,472],[447,479],[445,487],[441,488],[439,481],[440,472],[439,461],[438,450],[439,440],[438,430]]],'visual_rationale':'Longitudinal lit bark grain forms a continuous central face. Polygon steps inward at changes in trunk edge/shadow. Dark brown bark fissures retained as source appearance, not filtered by color.','explicit_exclusions':'No pixels at y490 or lower. Right green ivy/ground margin and dark left outer silhouette excluded by manual interior; visible-neighborhood boundary remains mixed, not an accepted bark mask.','limits':'This is source-role proposal only; rootground y490+ and side/rear bark remain separate. Geometry and exact saved receiver are unproved.'}, {'id':'left-fork-stone-window','class':'stone_interior_with_mixed_neighborhood','context_box':[344,319,391,371],'visible_neighborhood':[[347,325],[358,324],[369,325],[379,332],[383,344],[379,356],[366,363],[351,357],[345,343]],'interior_polygons':[[[355,328],[359,328],[360,331],[359,334],[357,333],[355,331]]],'visual_rationale':'The broad source neighborhood contains pale stone-like faces but dense gold leaves, dark twigs and branch crossings. Only a small pale central-left window is sufficiently plausible to propose; broad polygon is explicitly mixed context.','explicit_exclusions':'All broad-neighborhood pixels outside the small interior remain HOLD. Gold/twig corridors around x350..354,y330..340; x361..368,y329..346; x373..382,y327..354; lower dark crossings y355+ are not proposed stone.','limits':'Cannot defend whole350..385,y325..365 as exposed stone. Even this small source window needs independent root role review; do not expand into similarly colored bark/leaf pixels.'}]
 for row in rows:
  outer=polygon(row['visible_neighborhood']);interior=np.zeros(native.shape,bool)
  for points in row['interior_polygons']:interior|=polygon(points)
  assert np.all(outer[interior]);proposal=interior&~native;assert not np.any(proposal&native);name=row['id'];Image.fromarray(proposal.astype('uint8')*255).save(out/f'{name}-unassigned-interior.png');rgba=np.zeros_like(source);rgba[proposal]=source[proposal];Image.fromarray(rgba).save(out/f'{name}-unassigned-source-rgba.png');_,components=label(proposal);row.update(status='PROPOSAL_ONLY_REQUIRES_SOURCE_REVIEW_THEN_SAVED_RECEIVERS',neighborhood_pixels=int(outer.sum()),manual_interior_pixels=int(interior.sum()),native_foreground_excluded=int((interior&native).sum()),unassigned_proposal_pixels=int(proposal.sum()),connected_components=components,per_phase_proposal_native_overlap=[int((proposal&a).sum())for a in phases],exact_source_pixels_xy=[[int(x),int(y)]for y,x in np.argwhere(proposal)])
  box=tuple(row['context_box']);crop=src.crop(box).convert('RGB');scale=10;width,height=crop.width*scale,crop.height*scale;panelwidth=width+65;sheet=Image.new('RGB',(panelwidth*3,height+70),'#262626');d=ImageDraw.Draw(sheet);outline=crop.copy();od=ImageDraw.Draw(outline);od.line([(x-box[0],y-box[1])for x,y in row['visible_neighborhood']+[row['visible_neighborhood'][0]]],fill=(255,160,30),width=1)
  maskview=np.zeros((*native.shape,3),np.uint8);maskview[outer]=[55,55,55];maskview[outer&native]=[130,70,220];maskview[proposal]=[255,255,255]
  for col,(title,im)in enumerate([('UNMARKED source',crop),('Amber: mixed outer neighborhood',outline),('White: proposal / purple: native priority',Image.fromarray(maskview).crop(box))]):
   ox=col*panelwidth;sheet.paste(im.resize((width,height),Image.Resampling.NEAREST),(ox+45,45));d.text((ox+3,4),title,fill='white');d.text((ox+3,20),f'XYXY{box};10x nearest',fill='white')
   for x in range(box[0],box[2]):
    if x%5==0:d.text((ox+45+(x-box[0])*scale,32),str(x),fill='white')
   for y in range(box[1],box[3]):
    if y%5==0:d.text((ox+8,45+(y-box[1])*scale),str(y),fill='white')
  sheet.save(out/f'{name}-unmarked-and-proposal.png')
 report={'status':'TWO_PRIORITY_UNASSIGNED_SOURCE_PROPOSALS','pins':pins,'regions':rows,'native_union_pixels':int(native.sum()),'source_roles_not_assigned':True,'root_guidance':'Prioritize main trunk around440..454,y420..495 and exposed stone around350..385,y325..365; guidance is not pixel approval.','qualification':'Bark interior stops above y490 ivy/root boundary. Broad left-fork stone neighborhood is mixed/HOLD; only explicitly enumerated small interior proposed. All native pixels excluded without changing existing native source.','next':['Independent root source-role review of unmarked coordinate crops and exact interior lists.','If authorized, saved exact receiver and fullnative firsthit tests before any projection.','Do not widen stone based on gray model gaps, alpha complement or color similarity.'],'output_pins':{p.name:hashlib.sha256(p.read_bytes()).hexdigest()for p in out.iterdir()if p.is_file()}};(out/'receipt.json').write_text(json.dumps(report,indent=2)+'\n');print([(r['id'],r['manual_interior_pixels'],r['native_foreground_excluded'],r['unassigned_proposal_pixels'],r['connected_components'])for r in rows])
